INSERT INTO `content` VALUES (1,'Midnight Protocol','MOVIE','2024-02-15',128,'English','USA','16+','A cybersecurity analyst uncovers a global conspiracy hidden inside a classified network.'),(2,'The Last Monsoon','MOVIE','2023-07-21',142,'Hindi','India','13+','A journalist returns to her hometown and discovers secrets connected to a forgotten flood.'),(3,'Code Red','MOVIE','2025-01-10',118,'English','USA','16+','A team of engineers races against time to stop a catastrophic digital attack.'),(4,'Echoes of Time','MOVIE','2022-11-18',135,'English','UK','13+','A historian discovers a mysterious device capable of revealing fragments of the past.'),(5,'City of Dreams','MOVIE','2024-05-03',126,'Hindi','India','13+','An ambitious young designer tries to build a new life in Mumbai.'),(6,'Shadow House','MOVIE','2023-10-27',110,'English','USA','18+','A family moves into an isolated house where unexplained events begin occurring.'),(7,'Beyond the Stars','MOVIE','2025-03-14',151,'English','USA','13+','Astronauts discover an unexpected signal while exploring a distant planet.'),(8,'The Silent Witness','MOVIE','2024-08-09',121,'Hindi','India','16+','A courtroom investigation takes an unexpected turn when a crucial witness disappears.'),(9,'Parallel Lives','MOVIE','2023-03-17',130,'Tamil','India','13+','Two strangers discover that their lives are connected across different realities.'),(10,'Ocean Within','MOVIE','2022-06-24',115,'English','Australia','7+','A marine biologist documents the hidden ecosystem beneath a remote island.'),(11,'The Forgotten Kingdom','SERIES','2024-01-12',NULL,'English','UK','13+','A group of explorers discovers a kingdom believed to have disappeared centuries ago.'),(12,'Digital Hearts','SERIES','2025-02-07',NULL,'English','USA','13+','Young developers build an artificial intelligence that begins changing their lives.'),(13,'Mumbai Stories','SERIES','2023-09-01',NULL,'Hindi','India','16+','Interconnected stories of friendship, ambition and survival in Mumbai.'),(14,'Dark Horizon','SERIES','2024-06-14',NULL,'English','USA','18+','A detective investigates a chain of mysterious disappearances across the city.'),(15,'Campus Diaries','SERIES','2023-07-28',NULL,'Hindi','India','13+','Students navigate friendship, relationships and ambition during college life.'),(16,'The Quantum Key','SERIES','2025-04-18',NULL,'English','USA','16+','Scientists discover a quantum technology that could change the future of humanity.'),(17,'Kerala Chronicles','SERIES','2022-08-12',NULL,'Malayalam','India','13+','A family drama exploring generations of tradition, conflict and reconciliation.'),(18,'Beyond Reality','SERIES','2024-10-04',NULL,'English','Canada','16+','A virtual reality experiment begins producing events that cannot be explained.'),(19,'Rising Phoenix','SERIES','2023-11-10',NULL,'Tamil','India','13+','A young entrepreneur rebuilds her life after losing everything.'),(20,'The Final Signal','SERIES','2025-05-23',NULL,'English','USA','18+','A mysterious transmission warns humanity about an approaching threat.');
