INSERT INTO `genres` VALUES (1,'Action','Fast-paced stories involving conflict, adventure and physical challenges.'),(2,'Drama','Character-driven stories focused on emotions, relationships and life events.'),(3,'Comedy','Stories designed primarily to entertain through humor and amusing situations.'),(4,'Thriller','Suspenseful stories involving mystery, danger and unexpected events.'),(5,'Science Fiction','Stories involving advanced technology, science and futuristic concepts.'),(6,'Romance','Stories focused on romantic relationships and emotional connections.'),(7,'Horror','Stories involving fear, supernatural events and psychological suspense.'),(8,'Mystery','Stories centered around investigations, secrets and solving unknown events.'),(9,'Adventure','Stories involving exploration, journeys and challenging experiences.'),(10,'Family','Entertainment suitable for family audiences and centered around family relationships.'),(11,'Crime','Stories involving criminal investigations, law enforcement and criminal activity.'),(12,'Technology','Stories involving computers, artificial intelligence, cybersecurity and digital systems.');
